INSERT INTO public.curriculum_courses (course_code, grade, term, subject_name, learning_area, course_type, hours, description) VALUES
  ('ง21101', 'ม.1', 1, 'การงานอาชีพ', 'การงานอาชีพ', 'รายวิชาพื้นฐาน', 20, 'ศึกษาและวิเคราะห์ขั้นตอนการทำงานตามกระบวนการทำงาน โดยทำตามลำดับขั้นตอนที่วางแผนไว้ในการใช้อุปกรณ์อำนวยความสะดวกในการทำงานบ้าน การจัดและตกแต่งห้อง รู้จักวางแผนการทำงานเป็นกลุ่ม โดยใช้กระบวนการกลุ่มในการทำงานด้วยความเสียสละ ในการเตรียม ประกอบ จัด ตกแต่ง และบ ริการอาหาร การแปรรูปผลผลิตทางการเกษตร การประดิษฐ์ของใช้ ของตกแต่งจากวัสดุในท้องถิ่น สามารถตัดสินใจแก้ปัญหาการทำงานอย่างมีเหตุผลในการจัดสวนในภาชนะ การซ่อมแซมอุปกรณ์ เครื่องมือ เครื่องใช้ พร้อมทั้งแสวงหาความรู้ เพื่อนำมาประเมินผล ปรับปรุงงาน นำมาเป็นแนวทางใน การเลือกอาชีพ การมีเจตคติที่ดีต่อการประกอบอาชีพ และเห็นความสำคัญของการสร้างอาชีพเพื่อให้เกิดความตระหนักและเห็นคุณค่าของการทำงาน มีทักษะกระบวนการทำงาน ทักษะการจัดการ ทักษะกระบวนการแก้ปัญหา ทักษะการทำงานร่วมกัน และทักษะการแสวงหาความรู้ สามารถนำความรู้มาประยุกต์ใช้ในชีวิตประจำวันได้ มีความสามารถในการตัดสินใจ มีคุณธรรม จริยธรรม และค่านิยม ที่เหมาะสม รวมถึงมีจิตสำนึกในการใช้พลังงาน ทรัพยากร และสิ่งแวดล้อมอย่างประหยัดและคุ้มค่า'),
  ('ง21102', 'ม.1', 2, 'การงานอาชีพ', 'การงานอาชีพ', 'รายวิชาพื้นฐาน', 20, 'ศึกษาและวิเคราะห์ขั้นตอนการทำงานตามกระบวนการทำงาน โดยทำตามลำดับขั้นตอนที่วางแผนไว้ในการใช้อุปกรณ์อำนวยความสะดวกในการทำงานบ้าน การจัดและตกแต่งห้อง รู้จักวางแผนการทำงานเป็นกลุ่ม โดยใช้กระบวนการกลุ่มในการทำงานด้วยความเสียสละ ในการเตรียม ประกอบ จัด ตกแต่ง และบ ริการอาหาร การแปรรูปผลผลิตทางการเกษตร การประดิษฐ์ของใช้ ของตกแต่งจากวัสดุในท้องถิ่น สามารถตัดสินใจแก้ปัญหาการทำงานอย่างมีเหตุผลในการจัดสวนในภาชนะ การซ่อมแซมอุปกรณ์ เครื่องมือ เครื่องใช้ พร้อมทั้งแสวงหาความรู้ เพื่อนำมาประเมินผล ปรับปรุงงาน นำมาเป็นแนวทางใน การเลือกอาชีพ การมีเจตคติที่ดีต่อการประกอบอาชีพ และเห็นความสำคัญของการสร้างอาชีพเพื่อให้เกิดความตระหนักและเห็นคุณค่าของการทำงาน มีทักษะกระบวนการทำงาน ทักษะการจัดการ ทักษะกระบวนการแก้ปัญหา ทักษะการทำงานร่วมกัน และทักษะการแสวงหาความรู้ สามารถนำความรู้มาประยุกต์ใช้ในชีวิตประจำวันได้ มีความสามารถในการตัดสินใจ มีคุณธรรม จริยธรรม และค่านิยม ที่เหมาะสม รวมถึงมีจิตสำนึกในการใช้พลังงาน ทรัพยากร และสิ่งแวดล้อมอย่างประหยัดและคุ้มค่า'),
  ('ง22101', 'ม.2', 1, 'การงานอาชีพ', 'การงานอาชีพ', 'รายวิชาพื้นฐาน', 20, 'ศึกษา ค้นคว้า รวบรวม สังเกต สำรวจ บันทึก และแสวงหาความรู้ เพื่อใช้ในการพัฒนาการทำงานการจัดและตกแต่งบ้าน การดูแลรักษาและตกแต่งสวน การจัดการผลผลิต ใช้ทักษะกระบวนการแก้ปัญหาในการทำงาน การเตรียม ประกอบ จัด ตกแต่ง และบริการเครื่องดื่ม การเลี้ยงสัตว์ การประดิษฐ์ของใช้ของตกแต่งจากวัสดุในโรงเรียน หรือท้องถิ่น การติดต่อสื่อสาร และใช้บริการกับหน่วยงานต่าง ๆ มีจิตสำนึกในการทำงานและใช้ทรัพยากรในการปฏิบัติงานอย่างประหยัดและคุ้มค่า มีการเสริมสร้างประสบการณ์อาชีพการเตรียมตัวเข้าสู่อาชีพ และมีทักษะพื้นฐานที่จำเป็นสำห รับการประกอบอาชีพที่สนใจเพื่อให้เกิดความตระหนักและเห็นคุณค่าของการทำงาน มีทักษะกระบวนการทำงาน ทักษะการจัดการ ทักษะกระบวนการแก้ปัญหา ทักษะการทำงานร่วมกัน และทักษะการแสวงหาความรู้ สามารถนำความรู้มาประยุกต์ใช้ในชีวิตประจำวันได้ มีความสามารถในการตัดสินใจ มีคุณธรรม จริยธรรม และค่านิยม ที่เหมาะสม รวมถึงมีจิตสำนึกในการใช้พลังงาน ทรัพยากร และสิ่งแวดล้อมอย่างประหยัดและคุ้มค่า'),
  ('ง22102', 'ม.2', 2, 'การงานอาชีพ', 'การงานอาชีพ', 'รายวิชาพื้นฐาน', 20, 'ศึกษา ค้นคว้า รวบรวม สังเกต สำรวจ บันทึก และแสวงหาความรู้ เพื่อใช้ในการพัฒนาการทำงานการจัดและตกแต่งบ้าน การดูแลรักษาและตกแต่งสวน การจัดการผลผลิต ใช้ทักษะกระบวนการแก้ปัญหาในการทำงาน การเตรียม ประกอบ จัด ตกแต่ง และบริการเครื่องดื่ม การเลี้ยงสัตว์ การประดิษฐ์ของใช้ของตกแต่งจากวัสดุในโรงเรียน หรือท้องถิ่น การติดต่อสื่อสาร และใช้บริการกับหน่วยงานต่าง ๆ มีจิตสำนึกในการทำงานและใช้ทรัพยากรในการปฏิบัติงานอย่างประหยัดและคุ้มค่า มีการเสริมสร้างประสบการณ์อาชีพการเตรียมตัวเข้าสู่อาชีพ และมีทักษะพื้นฐานที่จำเป็นสำห รับการประกอบอาชีพที่สนใจเพื่อให้เกิดความตระหนักและเห็นคุณค่าของการทำงาน มีทักษะกระบวนการทำงาน ทักษะการจัดการ ทักษะกระบวนการแก้ปัญหา ทักษะการทำงานร่วมกัน และทักษะการแสวงหาความรู้ สามารถนำความรู้มาประยุกต์ใช้ในชีวิตประจำวันได้ มีความสามารถในการตัดสินใจ มีคุณธรรม จริยธรรม และค่านิยม ที่เหมาะสม รวมถึงมีจิตสำนึกในการใช้พลังงาน ทรัพยากร และสิ่งแวดล้อมอย่างประหยัดและคุ้มค่า'),
  ('ง23101', 'ม.3', 1, 'การงานอาชีพ', 'การงานอาชีพ', 'รายวิชาพื้นฐาน', 20, 'ศึกษาและเรียนรู้เกี่ยวกับขั้นตอนการทำงานตามกระบวนการทำงานในการซัก ตาก พับ เก็บเสื้อผ้าที่ต้องดูแลอย่างประณีต การสร้างชิ้นงาน หรือผลงาน ใช้ทักษะการทำงานร่วมกันในการเตรียม ประกอบอาหารประเภทสำรับและการประดิษฐ์บรรจุภัณฑ์จากวัสดุธรรมชาติ ใช้ทักษะการจัดการในการป ระกอบธุรกิจประเภทต่าง ๆ การขยายพันธุ์พืช การติดตั้งและประกอบผลิตภัณฑ์ มีจิตสำนึกในการทำงานและใช้ทรัพยากรในการปฏิบัติงานอย่างประหยัดและคุ้มค่า อภิปรายการหางานด้วยวิธีที่หลากหลาย วิเคราะห์แนวทางเข้าสู่อาชีพ และสามารถประเมินทางเลือกในการประกอบอาชีพที่สอดคล้อง กับความรู้ ความถนัด และความสนใจของตนเอง เพื่อการเสริมสร้างประสบการณ์อาชีพโดยใช้กระบวนการเรียนรู้ วิธีการสอนแบบกระบวนการปฏิบัติ วิธีสอนแบบโครงงานเป็นฐาน รวมทั้งใช้ทักษะการทำงานร่วมกันอย่างมีคุณธรรม และทักษะการจัดการในการทำงานเพื่อให้เกิดความตระหนักและเห็นคุณค่าของการทำงาน มีทักษะการทำงานร่วมกัน และทักษะการจัดการในการปฏิบัติงานตามขั้นตอนการทำงานอย่างมีประสิทธิภาพ สามารถนำความรู้ที่ได้ไปประยุกต์ใช้ในชีวิตประจำวัน รวมทั้งมีคุณธรรมในการทำงาน และมีจิตสำนึกในการใช้พลังงาน ทรัพยากร และสิ่งแวดล้อม'),
  ('ง23102', 'ม.3', 2, 'การงานอาชีพ', 'การงานอาชีพ', 'รายวิชาพื้นฐาน', 20, 'ศึกษาและเรียนรู้เกี่ยวกับขั้นตอนการทำงานตามกระบวนการทำงานในการซัก ตาก พับ เก็บเสื้อผ้าที่ต้องดูแลอย่างประณีต การสร้างชิ้นงาน หรือผลงาน ใช้ทักษะการทำงานร่วมกันในการเตรียม ประกอบอาหารประเภทสำรับและการประดิษฐ์บรรจุภัณฑ์จากวัสดุธรรมชาติ ใช้ทักษะการจัดการในการป ระกอบธุรกิจประเภทต่าง ๆ การขยายพันธุ์พืช การติดตั้งและประกอบผลิตภัณฑ์ มีจิตสำนึกในการทำงานและใช้ทรัพยากรในการปฏิบัติงานอย่างประหยัดและคุ้มค่า อภิปรายการหางานด้วยวิธีที่หลากหลาย วิเคราะห์แนวทางเข้าสู่อาชีพ และสามารถประเมินทางเลือกในการประกอบอาชีพที่สอดคล้อง กับความรู้ ความถนัด และความสนใจของตนเอง เพื่อการเสริมสร้างประสบการณ์อาชีพโดยใช้กระบวนการเรียนรู้ วิธีการสอนแบบกระบวนการปฏิบัติ วิธีสอนแบบโครงงานเป็นฐาน รวมทั้งใช้ทักษะการทำงานร่วมกันอย่างมีคุณธรรม และทักษะการจัดการในการทำงานเพื่อให้เกิดความตระหนักและเห็นคุณค่าของการทำงาน มีทักษะการทำงานร่วมกัน และทักษะการจัดการในการปฏิบัติงานตามขั้นตอนการทำงานอย่างมีประสิทธิภาพ สามารถนำความรู้ที่ได้ไปประยุกต์ใช้ในชีวิตประจำวัน รวมทั้งมีคุณธรรมในการทำงาน และมีจิตสำนึกในการใช้พลังงาน ทรัพยากร และสิ่งแวดล้อม')
