INSERT INTO public.curriculum_indicators (indicator_code, grade, standard, description) VALUES
  ('ง 1.1 ม.1/1', 'ม.1', 'ง 1.1', 'วิเคราะห์ขั้นตอนการทำงานตามกระบวนการทำงาน'),
  ('ง 1.1 ม.1/2', 'ม.1', 'ง 1.1', 'ใช้กระบวนการกลุ่มในการทำงานด้วยความเสียสละ'),
  ('ง 1.1 ม.1/3', 'ม.1', 'ง 1.1', 'ตัดสินใจแก้ปัญหาการทำงานอย่างมีเหตุผล'),
  ('ง 1.1 ม.2/1', 'ม.2', 'ง 1.1', 'ใช้ทักษะการแสวงหาความรู้เพื่อพัฒนาการทำงาน'),
  ('ง 1.1 ม.2/2', 'ม.2', 'ง 1.1', 'ใช้ทักษะกระบวนการแก้ปัญหาในการทำงาน'),
  ('ง 1.1 ม.2/3', 'ม.2', 'ง 1.1', 'มีจิตสำนึกในการทำงานและใช้ทรัพยากรในการปฏิบัติงาน อย่างประหยัดและคุ้มค่า'),
  ('ง 1.1 ม.3/1', 'ม.3', 'ง 1.1', 'อภิปรายขั้นตอนการทำงานที่มีประสิทธิภาพ'),
  ('ง 1.1 ม.3/2', 'ม.3', 'ง 1.1', 'ใช้ทักษะในการทำงานร่วมกันอย่างมีคุณธรรม'),
  ('ง 1.1 ม.3/3', 'ม.3', 'ง 1.1', 'อภิปรายการทำงานโดยใช้ทักษะการจัดการเพื่อการประหยัดพลังงานทรัพยากร และสิ่งแวดล้อม'),
  ('ง 2.1 ม.1/1', 'ม.1', 'ง 2.1', 'อธิบายแนวทางการเลือกอาชีพ'),
  ('ง 2.1 ม.1/2', 'ม.1', 'ง 2.1', 'มีเจตคติที่ดีต่อการประกอบอาชีพ'),
  ('ง 2.1 ม.1/3', 'ม.1', 'ง 2.1', 'เห็นความสำคัญของการสร้างอาชีพ'),
  ('ง 2.1 ม.2/1', 'ม.2', 'ง 2.1', 'อธิบายการเสริมสร้างประสบการณ์อาชีพ'),
  ('ง 2.1 ม.2/2', 'ม.2', 'ง 2.1', 'ระบุการเตรียมตัวเข้าสู่อาชีพ'),
  ('ง 2.1 ม.2/3', 'ม.2', 'ง 2.1', 'มีทักษะพื้นฐานที่จำเป็นสำหรับการประกอบอาชีพที่สนใจ'),
  ('ง 2.1 ม.3/1', 'ม.3', 'ง 2.1', 'อธิบายการหางานด้วยวิธีที่หลากหลาย'),
  ('ง 2.1 ม.3/2', 'ม.3', 'ง 2.1', 'วิเคราะห์แนวทางเข้าสู่อาชีพ'),
  ('ง 2.1 ม.3/3', 'ม.3', 'ง 2.1', 'ประเมินทางเลือกในการประกอบอาชีพที่สอดคล้องกับความรู้ความถนัด และความสนใจของตนเอง')
INSERT INTO public.curriculum_units (course_code, unit_no, seq, name, hours, essence) VALUES
  ('ง21101', 1, 1, 'เรียนรู้กระบวนการทำงาน', 6, 'กระบวนการทำงานเป็นการทำงานตามขั้นตอนด้วยตนเอง โดยการฝึกวิธีการทำงานอย่างสม่ำเสมอ เพื่อให้สามารถทำงานได้บรรลุเป้าหมาย กระบวนการทำงานมี 4 ขั้นตอน ได้แก่การวิเคราะห์งาน การวางแผนในการทำงานการลำดับงานตามขั้นตอน งาน และการประเมินผลการทำงานการทำงานแบบกระบวนการกลุ่มเป็นการทำงานร่วมกันตั้งแต่ 2 คนขึ้นไป โดยสมาชิกภายในกลุ่มต้องมีการสื่อสารที่ดี มีปฏิสัมพันธ์ร่วมกัน สามารถแลกเปลี่ยนความคิดเห็นซึ่งกันและกัน แบ่งงานกันทำตามบทบาทหน้าที่ที่ได้รับมอบหมาย โดยมีวัตถุประสงค์ในการทำงานร่วมกันให้สำเร็จอย่างมีประสิทธิภาพและต้องมีการประเมินผลที่ดีเพื่อปรับปรุงพัฒนาผลงานให้ดีมากยิ่งขึ้นต่อไปการทำงานด้วยความเสียสละเป็นคุณธรรมในการทำงานด้วยกระบวนการกลุ่ม เพราะการทำงานเป็นกลุ่มสมาชิกแต่ละคนย่อมมีความคิดเห็นที่แตกต่างทำให้เกิดปัญหาหรือความขัดแย้ง ดังนั้น หากสมาชิกทุกคนภายในกลุ่มเป็นผู้ที่มีเหตุผล มีความเสียสละ มีคุณธรรมจริยธรรม มีสัมพันธภาพที่ดีต่อกันภายในกลุ่มจะทำให้การทำงานกลุ่มนั้นประสบความสำเร็จ'),
  ('ง21101', 4, 2, 'การประดิษฐ์ของใช้ของตกแต่งจากวัสดุในท้องถิ่น', 6, 'การประดิษฐ์ของใช้ของตกแต่งจากวัสดุในท้องถิ่น เป็นการใช้วัสดุที่มีในแต่ละท้องถิ่นมาสร้างสรรค์หรือออกแบบเป็นผลิตภัณฑ์ที่ให้ประโยชน์ใช้สอยตรงกับความต้องการ และควรคำนึงถึงหลักการประดิษฐ์ โดยเลือกใช้วัสดุอุปกรณ์ และเครื่องมือต่าง ๆ อย่างเหมาะสมการประดิษฐ์ของใช้จากวัสดุในท้องถิ่น เป็นการนำวัสดุต่าง ๆ ที่มีอยู่ในท้องถิ่นมาประดิษฐ์เป็นของใช้ ของตกแต่งดังนั้น ควรเลือกใช้วัสดุที่หาได้ง่าย หรือมีราคาที่ไม่แพง แล้วนำมาออกแบบการประดิษฐ์ชิ้นงานตามกระบวนการทำงาน โดยใช้กระบวนการกลุ่มด้วยความเสียสละ และตัด สินใจแก้ปัญหาอย่างมีเหตุผลงานประดิษฐ์จากวัสดุในท้องถิ่น เป็นการนำวัสดุต่าง ๆ ที่มีอยู่ในท้องถิ่นมาประดิษฐ์เป็นของใช้ ของตกแต่งบ้านเพื่อนำมาใช้สอย หรือนำมา ใช้ประโยชน์ในชีวิตประจำวัน ซึ่งแบ่งตามลักษณะการใช้งานและแบ่งตามลักษณะการนำไปใช้ได้ไม่ว่าจะเป็น ใช้บรรจุสิ่งของ ใช้ในงานประเพณีวัฒนธรรม ใช้เป็นอุปกรณ์ในการทำงานใช้ประดับตกแต่งบ้านหรือสถานที่ต่าง ๆ และใช้ประดับร่างกาย'),
  ('ง21101', 5, 3, 'โลกของอาชีพ', 8, 'การประกอบอาชีพมีความสำคัญต่อการดำรงชีวิตของมนุษย์เพื่อสร้างรายได้ให้กับตนเองและครอบครัวช่วยเสริมสร้างและพัฒนาคุณภาพชีวิตให้ดีขึ้นอีกทั้งยังช่วยพัฒนาประเทศชาติให้ มีความเจริญก้าวหน้า ซึ่งอาชีพที่ดีจะต้องเป็นอาชีพที่สุจริต ไม่ผิดกฎหมายไม่ขัดต่อศีลธรรม และเป็นที่ยอมรับของสังคมการศึกษา ค้นคว้าหาข้อมูลเกี่ยวกับการประกอบอาชีพ ถือว่าเป็นแนวทางในการเลือกอาชีพเพื่อ จะ นำไปใช้ประกอบ ในการตัดสินใจเลือกประกอบอาชีพในอนาคต เนื่องจากปัจจุบันมีอาชีพให้เลือกมากมายดังนั้น จึงควรเลือกประกอบอาชีพให้เหมาะสมกับความสามารถและความถนัดของตนเองกระบวนการตัดสินใจเลือกอาชีพมีความสำคัญต่อการตัดสินใจเลือกอาชีพ การตัดสินใจที่ดีจะต้องมีข้อมูลเป็นพื้นฐาน มีการวิเคราะห์ตนเอง และวิเคราะห์อาชีพใช้เป็นเหตุผลในการตัดสินใจเลือกประกอบอาชีพได้อย่างเหมาะสมการสร้างอาชีพสามารถนำความรู้ ความเข้าใจ และทักษะกระบวนเรียนรู้จากการทำงานมาปรับใช้ รวมถึงการนำเทคโนโลยีต่าง ๆเข้ามาช่วยเหลือในการสร้างสรรค์ผลงานหรือผลิตชิ้นงานตามความสนใจ ความสามารถ และความพร้อมของตนเองเพื่อนำมาจัดจำหน่ายสร้างรายได้ให้แก่ตนเองและครอบครัว'),
  ('ง21102', 2, 1, 'การดูแลรักษาบ้าน', 10, 'บ้านเป็นสถานที่ที่สมาชิกในครอบครัวอาศัยอยู่ร่วมกันอย่างมีความสุขสมาชิกทุกคนจะต้องรู้จักบทบาท หน้าที่ของตนเองและสร้างสัมพันธภาพที่ดีเพื่อให้บ้านและความเป็นอยู่ ภายในบ้านมีบรรยากาศที่อบอุ่นการวางแผนการทำงานบ้าน เป็นการกำหนดการทำงานไว้ล่วงหน้า โดย ต้อง มีจุดมุ่งหมายในการทำงานอย่างชัดเจน และจะต้องทำตาม ลำดับ ขั้นตอนของกระบวนการทำงานเพื่อให้การทำงานมีความเป็นระบบมากขึ้นการดูแลรักษาบ้านให้สะอาดเป็นระเบียบเรียบร้อย น่าอยู่อาศัยได้นั้น จะต้องมีวิธีการและขั้นตอนขอ ง กระบวนการทำงานดูแลรักษาบ้านแต่ขณะที่ทำงาน บ้าน นั้นควรระมัดระวังในเรื่องของความปลอดภัยในการใช้อุปกรณ์อำนวยความสะดวก และความปลอดภัย จาก การใช้สารเคมีในการทำความสะอาดบ้านด้วย บ้านที่มีความสวยงาม สะอาดและเป็นระเบียบเรียบร้อย เป็นสิ่งที่สมาชิกทุกค น พึงปรารถนา สมาชิกในครอบครัวต้องหมั่นทำความสะอาดและตกแต่งห้องต่าง ๆ ในบ้านให้สวยงาม เป็นระเบียบเรียบร้อยอยู่เสมอ เพื่อให้บ้านน่าอยู่อาศัยมากยิ่งขึ้น อีกทั้งการตกแต่งบ้านให้ มีความ สวยงามยังสามารถสร้างความประทับใจให้ผู้ที่มาเยี่ยมเยียนได้อีกด้วย'),
  ('ง21102', 3, 2, 'อาหารกับการดำรงชีวิต', 10, 'การเลือกซื้อวัตถุดิบเพื่อ จะ นำมาใช้ในการประกอบอาหาร และการเลือกซื้ออาหารเพื่อนำมาบริโภค เราควรเลือกอาหารที่ถูกสุขลักษณะและมีคุณค่าทาง ด้านโภชนาการ เราจึงต้องมีความรู้ ความเข้าใจในการเลือกซื้อวัตถุดิบและอาหารเพื่อจะได้ตัดสินใจเลือกซื้อได้อย่างถูกต้องเหมาะสมตามหลักการการประกอบอาหารที่ดีจะต้องคำนึงถึงสุขภาพความสะอาด สุขลักษณะและความปลอดภัยของผู้ที่จะรับประทานอาหารนั้น ๆ ซึ่งจะต้องเริ่มต้นตั้งแต่การเลือกใช้อุปกรณ์เครื่องมือ เครื่องใช้ในการประกอบอาหาร การเตรียมวัตถุดิบ และจัดตกแต่งอาหารให้สวยงามเพิ่มความน่ารับประทานของอาหาร ซึ่งการจะปฏิบัติงานนั้นได้ดีต้องเริ่มจากการกำหนดเป้าหมายการวิเคราะห์ขั้นตอนการทำงาน ประเภท ต่าง ๆการปฏิบัติงาน และการตัดสินใจแก้ปัญหาที่เกิดขึ้นอย่างมีเหตุผลส่งผลให้การทำงานเป็นไปตามขั้นตอนและได้ผลงานที่มีประสิทธิภาพการแปรรูปผลผลิตทางการเกษตร รวมทั้งการประกอบอาหารจากอาหารแปรรูป เราจำเป็นต้องมีการสืบค้นข้อมูลและวางแผนในการทำงานโดยเริ่มจากการวิเคราะห์งานที่จะปฏิบัติเพื่อให้สามารถทำงานตามกระบวนการกลุ่มได้ด้วยความเสียสละอย่างมีประสิทธิภาพ ตัดสินใจแก้ไขปัญหาในการทำงานเพื่อให้ผลงานการแปรรูปผลผลิตทางเกษตรเป็นผลงานที่มีคุณภาพ'),
  ('ง22101', 1, 1, 'ทักษะในการทำงานเพื่อการดำรงชีวิต', 2, 'การทำงานเพื่อการดำรงชีวิตอาจมีปัญหาที่ต้องแก้ไข ผู้ปฏิบัติงานต้องมีความรู้ ความสามารถ เทคนิค วิธีการต่าง ๆ มาใช้เพื่อให้งานสำเร็จตามเป้าหมายซึ่งต้องพัฒนาทักษะของตนเองให้หลากหลาย เช่นทักษะการแสวงหาความรู้ทักษะการแก้ปัญหาทักษะการติดต่อสื่อสารการทำความเข้าใจทักษะต่าง ๆ จะช่วยให้สามารถปฏิบัติงานได้อย่างมีประสิทธิภาพ ทั้งยังเป็นรากฐานในการทำงานในอนาคต ช่วยสร้างจิตสำนึกในการทำงานและใช้ทรัพยากรในการปฏิบัติงานอย่างประหยัด คุ้มต่าและมีประสิทธิภาพสูงสุด'),
  ('ง22101', 2, 2, 'การจัดตกแต่งบ้านและบริเวณบ้าน', 8, 'บ้านเป็นสถานที่สำหรับพักผ่อน นอนหลับบังแดด ลม ฝน เป็นศูนย์รวมของสมาชิกในครอบครัวที่จะใช้ชีวิตอยู่ร่วมกันอย่างมีความสุข มีความรัก ความอบอุ่นและความปลอดภัยในการดำรงชีวิต บ้านที่น่าอยู่ไม่จำเป็นต้องหลังใหญ่แต่ต้องมีความปลอดภัยต่อสมาชิกในครอบครัว มีความรัก ความเข้าใจและความเอื้ออาทรต่อกันบ้านจึงจะเป็นบ้านที่น่าอยู่อาศัย มีบรรยากาศอบอุ่น สมาชิกในครอบครัวอยู่ร่วมกันอย่างมีความสุข และต้องมีการจัดตกแต่งบ้านให้สวยงามน่าอยู่ และเป็นที่พึงพอใจของสมาชิกในครอบครัวการจัดและตกแต่งบ้านเพื่อให้บ้านมีความสวยงาม ร่มรื่น มีบรรยากาศที่ดี จัดและตกแต่งได้อย่างสวยงามตามรสนิยมของสมาชิกในครอบครัว ทั้งในบ้านและบริเวณบ้าน เพื่อให้บ้านมีความสวยงามครบทุกส่วน ทั้งการจัดและตกแต่งบ้านที่มีบริเวณและไม่มีบริเวณ รวมถึงการจัดสวนในบริเวณบ้านก็สามารถจัดและตกแต่งให้สวยงามได้ โดยการจัดสวยที่นำเอาองค์ประกอบทั้งที่เป็นธรรมชาติและสิ่งที่มนุษย์สร้างขึ้นมาผสมผสานกัน เพื่อให้เกิดสภาพแวดล้อมและบรรยากาศที่ดีในบริเวณบ้าน และเป็นมุมพักผ่อนของสมาชิกในครอบครัวซึ่งการจัดบ้านและสวนควรคำนึงถึงตัวบ้านพื้นที่ และรูปแบบ และการเลือกรูปแบบการจัดจะต้องคำนึงให้เหมาะสมกับบ้าน เพราะจะช่วยทำให้บ้านมีความสวยงามยิ่งขึ้นโดยรูปแบบการจัดบ้านและการจัดสวนมีหลากหลายรูปแบบขึ้นอยู่กับความต้องการ ความพึงพอใจของผู้อาศัย และความเหมาะ สมของบ้านและบริเวณบ้าน'),
  ('ง22101', 3, 3, 'เครื่องดื่มและการบริการ', 6, 'ในปัจจุบันเครื่องดื่มที่จำหน่ายมีมากมายทั้งแบบมีประโยชน์และแบบที่เป็นอันตรายต่อร่างกายเพราะฉะนั้นเราจึงต้องรู้จักชนิดของเครื่องดื่มและรู้หลักในการเลือกบริโภคเครื่องดื่ม เพื่อจะได้เลือกบริโภคเครื่องดื่มที่มีคุณค่าต่อร่างกาย และมีความเหมาะสมกับตนเองเพราะเครื่องดื่มเหล่านั้นจะช่วยเสริมสร้างความแข็งแรงของร่างกายเสริมสร้างภูมิต้านทานโรคอี กทั้งยังช่วยพัฒนาการเจริญเติบโตของร่างกายให้เป็นไปอย่างเหมาะสมการประกอบเครื่องดื่มชนิดต่าง ๆ ต้องอาศัยการแสวงหาความรู้เพื่อเลือกประกอบเครื่องดื่มตามหลักการเลือกบริโภค โดยสืบค้นหาสูตรเครื่องดื่มที่เหมาะสมกับบุคคลที่จะบริโภคเพื่อให้ได้เครื่องดื่มที่มีรสชาติดีและมีประโยชน์ต่อร่างกา ยการประกอบเครื่องดื่มและการบริการเครื่องดื่มจำเป็นต้องมีการแสวงหาความรู้เพื่อให้สามารถสร้างเครื่องดื่มชนิดใหม่ที่มีรสชาติดีและมีการบริการที่ดีสามารถสร้างความประทับใจให้กับผู้ที่ได้ลิ้มรส โดยใช้ทรัพยากรอย่างประหยัดและคุ้มค่าในการปฏิบัติงานและแก้ปัญหาต่าง ๆ ที่เกิดขึ้นในการทำงานได้อย่างมีเหตุผ ล'),
  ('ง22101', 4, 4, 'งานช่างในบ้าน', 4, 'งานช่างจัดเป็นพื้นฐานในการดำรงชีวิตเราควรศึกษาเพื่อนำไปใช้ในการซ่อมแซมบำรุงรักษา ตลอดจนสามารถสร้างหรือประดิษฐ์สิ่งต่าง ๆ เพื่อใช้ในการดำเนินชีวิต หรือเพื่อประกอบอาชีพในอนาคต อีกทั้งยังเป็นการทำงานที่มีขั้นตอนและมีกระบวนการทำงานที่จะต้องศึกษา เพื่อให้ เกิดความรู้ ความเข้าใจ และจะได้ลงมือปฏิบัติงานได้อย่างมีประสิทธิภาพ'),
  ('ง22102', 5, 1, 'การประดิษฐ์ของใช้จากวัสดุในท้องถิ่น', 8, 'การประดิษฐ์ของใช้ของตกแต่งนับว่าเป็นกิจกรรมที่ต้องอาศัยทักษะความชำนาญ ดังนั้นควรฝึกปฏิบัติเป็นประจำอย่างสม่ำเสมอ รวมถึงการมีใจรักในการทำงาน ประดิษฐ์โดยใช้ความคิดสร้างสรรค์เพื่อให้เกิดผลงานที่มีรูปแบบแปลกใหม่ โดยใช้วัสดุที่มีอยู่ภายในโรงเรียนหรือภายในท้องถิ่นมาประดิษฐ์เป็นของใช้ของตกแต่งให้เกิดประโยชน์สูงสุดในการใช้สอยและคุ้มค่าในการทำงานมากที่สุด ทั้งนี้ผู้ประดิษฐ์ที่ดีจะต้องแสวงหาความรู้เพราะการแสวงหาความรู้จะทำให้ผู้ประดิษฐ์เกิดทักษะการแก้ปัญหาเฉพาะหน้าและนำมาปรับใช้ในการทำงานประดิษฐ์ได้อย่างถูกต้องเหมาะสมรวมทั้งผู้ประดิษฐ์ที่ดีต้องยึดหลักในการปฏิบัติงานประดิษฐ์และต้องคำนึงถึงความปลอดภัยในการปฏิบัติงานอย่างรอบคอบกระบวนการจัดการกับผลผลิตที่ได้จากงานประดิษฐ์ไปสู่เป้าหมายตามที่วางแผนไว้ ทั้งนี้ผู้ประดิษฐ์จะต้องทราบว่าผลงานดังกล่าวประดิษฐ์ขึ้นเพื่อวัตถุประสงค์ใดประดิษฐ์ขึ้นเพื่อใช้เองหรือเพื่อจัดจำหน่ายเพราะการออกแบบบรรจุภัณฑ์ เป็นส่วนสำคัญที่จะช่วยให้ผลผลิตมีคุณค่าและน่าสนใจการจัดจำหน่ายผ ลงานประดิษฐ์ เป็นการดำเนินการเพื่อนำผลผลิตที่ได้ไปจัดจำหน่าย เพื่อแลกเปลี่ยนเป็นเงินโดยมุ่งหวังผล กำ ไรจากการจัดจำหน่าย ดังนั้นผู้จำหน่ายจึงต้องหาวิธีการต่าง ๆ ให้ผู้ซื้อเกิดความประทับใจในสินค้าและบริการให้ได้มากที่สุดตามหลักการที่ควรปฏิบัติเพื่อประโยชน์สูงสุดของทั้งผู้บริโภคและผู้จัดจำหน่าย'),
  ('ง22102', 6, 2, 'การเลี้ยงสัตว์ในบริเวณบ้าน', 4, 'การเลี้ยงสัตว์ในบริเวณบ้านมีความสำคัญต่อการดำรงชีวิตของสมาชิกในครอบครัว ทำให้ได้เรียนรู้ทักษะที่จำเป็นในการเลี้ยงสัตว์ไม่ว่าจะเป็นการเข้าใจความเป็นอยู่ของสัตว์ หรือลักษณะนิสัยของสัตว์ อีกทั้งยังสร้างความเพลิดเพลินในการเลี้ยงสัตว์ ทำให้ผู้ที่เลี้ยงสัตว์ มีสุขภาพจิตที่ดี มีความอ่อนโยน และความเมตตา แต่ก่อนการตัดสินใจเลือกเลี้ยงสัตว์แต่ละชนิด ผู้เลี้ยงควรคำนึงถึงปัจจัยต่างๆ ที่เกี่ยวข้องไม่ว่าจะเป็นสถานที่ชนิดของสัตว์เลี้ยงและปัจจัยต่าง ๆ รวมทั้งวัตถุประสงค์ของผู้เลี้ยงว่าจะดำเนินการเลี้ยงสัตว์เพื่อความเพลิด เพลินหรือเพื่อนำไปบริโภค มีสัตว์หลายประเภทที่เราสามารถเลี้ยงในบริเวณบ้านได้ เช่น การเลี้ยงปลาสวยงาม ซึ่งการเลี้ยงปลาสวยงามจะส่งผลต่อผู้เลี้ยงและสมาชิกในครอบครัวเป็นอย่างมากเพราะเป็นการฝึกความรับผิดชอบ ความดูแลเอาใจใส่ ความอดทน และความมีวินัยของผู้เลี้ยงดังนั้นเพื่อให้เกิดการเลี้ยงปลาสวยงามที่มีประสิทธิภาพ ผู้เลี้ยงจึงควรศึกษาข้อมูลที่เกี่ยวข้องกับปลาสวยงามให้ดี ก่อนดำเนินการเลี้ยงปลาสวยงาม ตั้งแต่การคัดเลือกชนิดพันธุ์ปลาปัจจัยที่สำคัญในการเลี้ยงและลักษณะนิสัยของปลาสวยงาม'),
  ('ง22102', 7, 3, 'การเสริมสร้างประสบการณ์เพื่อเข้าสู่อาชีพ', 8, 'การเห็นความสำคัญของการเสริมสร้างประสบการณ์อาชีพจะช่วยให้นักเรียนเกิดความกระตือรือร้นในการค้นหาและรู้จักตนเองเกี่ยวกับความสนใจและความถนัดในเรื่องอาชีพซึ่งจะทำให้นักเรียนสามารถตัดสินใจวางแผนในเรื่องต่าง ๆ เพื่อให้ตนเองเข้าสู่อาชีพที่ตนเองต้องการได้ ซึ่งใ นปัจจุบันมีหลายอาชีพที่สามารถสร้างรายได้ให้กับนักเรียนและบุคคลทั่วไปทำให้การเสริมสร้างประสบการณ์อาชีพมีสิ่งที่นักเรียนต้องนำมาพิจารณาควบคู่ประกอบกับความสนใจในอาชีพนั้น ๆ ได้แก่ สถานการณ์ด้านแรงงานความรู้ที่ต้องมีและความสามารถของตนเองกับอาชีพที่สนใจและผลต อบแทนที่จะได้รับจากการประกอบอาชีพนั้น ๆ ซึ่งการรู้ข้อมูลเหล่านีร้เพื่อเป็นการเตรียมความพร้อมและสั่งสมประสบการณ์อาชีพนั้น ๆ และนำข้อมูลเหล่านี้มาพิจารณาร่วมกันในการเลือกประกอบอาชีพที่นักเรียนสนใจซึ่งจะเป็นผลดีต่อนักเรียนที่จะเลือกเส้นทางไปสู่อาชีพนั้น ๆได้ อย่างเหมาะสมการฝึกประสบการณ์ก่อนเข้าสู่อาชีพเป็นการเตรียมตัวเข้าสู่อาชีพที่สนใจ โดยการค้นหาตำแหน่งงานที่สนใจ เพื่อศึกษาคุณสมบัติของตำแหน่งงานนั้น รวมถึงการเขียน Resume ของตนเองให้เหมาะสมกับอาชีพ และสามารถนำข้อมูลที่ได้มาพัฒนาตนเอง เพื่อเตรียมตัวเข้าสู่อาชีพในอนาคต'),
  ('ง23101', 1, 1, 'หลักการทำงานเพื่อการดำรงชีพ', 2, 'การทำงานในชีวิตประจำวันไม่ว่าจะเป็นการทำงานบ้านหรือการทำงานเพื่อประกอบอาชีพ ผู้ปฏิบัติงานจำเป็นต้องนำทักษะต่างๆ มาประยุกต์ใช้ในการปฏิบัติงานอย่างเหมาะสมเช่น ทักษะการทำงานร่วมกัน ทักษะการจัดการซึ่งการเรียนรู้และมีทักษะดังกล่าวจะช่วยให้สามารถปฏิบัติงานได้อย่างถูกต้อง รวดเร็ว ลดการใช้วัสดุ อุปกรณ์เครื่องมือ เครื่องใช้ ลดการใช้พลังงาน รวมถึงสามารถปฏิบัติงานได้สำเร็จอย่างมีประสิทธิภาพ'),
  ('ง23101', 2, 2, 'ผ้าและการตัดเย็ย', 8, 'การทำงานร่วมกันอย่างมีประสิทธิภาพ เป็นความสามารถของบุคคลในการทำงานร่วมกัน โดยต้องอาศัยทักษะการจัดการในการวางแผนการปฏิบัติงาน การจัดการที่ดีย่อมส่งผลให้ผู้ปฏิบัติงานเกิดความคล่องตัว งานเป็นระบบและทำให้งานสำเร็จตามเป้าหมายที่กำหนดไว้'),
  ('ง23101', 3, 3, 'อาหารประเภทสำรับ', 6, 'การดูแลรักษาเสื้อผ้าและเครื่องแต่งกายเป็นการทำความสะอาดและเก็บรักษาเสื้อผ้าและเครื่องแต่งกายให้คงอยู่ในสภาพดีด้วยวิธีการต่าง ๆซึ่งการดูแลรักษาเสื้อผ้าและเครื่องแต่งกายมิใช่เป็นเพียงแค่การทำความสะอาด แต่ยังรวมถึงการจัดเก็บ การซ่อมแซมและการบำรุงรักษาเพื่ อให้เสื้อผ้าอยู่ในสภาพดี สวมใส่ได้นาน เพื่อช่วยลดค่าใช้จ่ายไม่ให้สิ้นเปลืองไปกับการซื้อเสื้อผ้าและเครื่องแต่งกายใหม่ และผู้ที่สาวมใส่เสื้อผ้าและเครื่องแต่งกายที่เรียบร้อย สะอาดเหมาะสมกับบุคลิกภาพและวัยของผู้สวมใส่ จะช่วยส่งเสริมบุคลิกภาพของผู้สวมใส่ให้ดูดียิ่งขึ้นด้วย'),
  ('ง23101', 4, 4, 'การปฏิบัติงานช่างในบ้าน', 4, 'การซ่อมแซมเสื้อผ้าเป็นทักษะพื้นฐานในชีวิตประจำวันที่มนุษย์พึงมี เพราะจะช่วยให้สามารถยืดอายุการใช้งานของเสื้อผ้า ลดค่าใช้จ่าย และส่งเสริมการใช้ทรัพยากรอย่างคุ้มค่า อีกทั้งยังช่วยฝึกฝนให้ปฏิบัติงานด้วยความประณีต อดทน และมีความรับผิดชอบในการทำงาน'),
  ('ง23102', 5, 1, 'การประดิษฐ์บรรจุภัณฑ์จากวัสดุธรรมชาติ', 5, 'การตกแต่งเสื้อผ้าเป็นวิธีการที่ช่วยดัดแปลงแก้ไขเสื้อผ้าให้มีความสวยงาม แปลกใหม่ หรือมีความทันสมัยมากขึ้นโดยการตกแต่งเสื้อผ้านั้นสามารถนำวัสดุต่าง ๆ มาใช้ในการตกแต่งเพื่อเพิ่มความสวยงามให้กับเสื้อผ้า ซึ่งอาจใช้วัสดุที่มีอยู่ใกล้ตัว เพื่อช่วยประหยัดค่าใ ช้จ่ายสามารถปฏิบัติได้หลายวิธีขึ้นอยู่กับความเหมาะสมกับลักษณะของเสื้อผ้าและจะต้องคำนึงถึงหลักการตกแต่งเสื้อผ้าร่วมด้วย เพื่อให้การตกแต่งเป็นไปอย่างมีประสิทธิภาพ'),
  ('ง23102', 6, 2, 'การขยายพันธุ์พืช', 4, 'การตกแต่งดัดแปลง และการตัดเย็บเป็นงานที่สามารถแสวงหาความรู้และทำได้ด้วยตนเอง ซึ่งผู้ปฏิบัติงานต้องมีการใช้ความคิดสร้างสรรค์ ในการสร้างผลงาน โดยอาศัยการทำงานตามลำดับขั้นตอนและวางแผนการทำงานร่วมกันเพื่อประหยัดทรัพยากร ตลอดจนสามารถนำผลงานการตัดเย็บไปใช้ประโยชน์ในชีวิตประจำวัน'),
  ('ง23102', 7, 3, 'การดำเนินงานธุรกิจ', 8, 'อาหารเป็นหนึ่งปัจจัยที่มีความสำคัญต่อการดำเนินชีวิตของมนุษย์ซึ่งแต่ละภาคจะมีอาหารพื้นถิ่นเป็นของตนเองที่มีเอกลักษณ์ที่แตกต่างกันทั้งทางด้านวัฒนธรรมขนบธรรมเนียม ประเพณีอาชีพ รวมทั้งแหล่งอาหารของผู้คนในท้องถิ่นซึ่งอาหารสำรับไทยจัดเป็นทรดกทางวัฒนธรรมการกินของชาติที่คนไทยปฏิบัติ สืบทอดกันมายาวนานจนถึงปัจจุบัน'),
  ('ง23102', 8, 4, 'แนวทางการเข้าสู่อาชีพ', 3, 'อาหารประเภทสำรับเป็นรูปแบบการจัดอาหารของไทยที่สะท้อนวัฒนธรรมการกินอยู่และการแบ่งปัน อาหารแต่ละสำรับจะประกอบด้วยอาหารหลากหลายชนิดเช่น แกง ต้ม ผัด ทอดน้ำพริก และผักสดเพื่อให้ได้รับรสชาติที่หลากหลายและสารอาหารครบถ้วน การจัดสำรับยังเน้นความสวยงาม ความประ ณีตและความสมดุลของรสชาติ อาหารแต่ละอย่างจะถูกจัดวางในภาชนะที่เหมาะสมและเรียงอย่างมีระเบียบ การรับประทานอาหารแบบสำรับยังเสริมสร้างความสัมพันธ์ในครอบครัวและชุมชนเพราะมักนิยมรับประทานร่วมกันนอกจากนี้ยังสะท้อนถึงภูมิปัญญาในท้องถิ่นการเลือกใช้วัตถุดิบตามฤดูกาลและวิธีการปรุงที่สืบทอดกันมา อาหารประเภทสำรับจึงเป็นทั้งมรดกทางวัฒนธรรมและวิถีชีวิตที่ควรอนุรักษ์ไว้')
