-- หลักสูตรสถานศึกษา: รายวิชาการงานอาชีพ ม.1–ม.3 (รหัสวิชา ง21101–ง23102)
-- ที่มา: ไฟล์ "16โครงสร้าง-การงาน-มต้น.pdf" ถอดเป็นตาราง แบ่ง 6 รายวิชาตามภาคเรียน ภาคเรียนละ 20 ชม.
--
-- ตาราง (ชื่อขึ้นต้น curriculum_):
--   curriculum_courses            รายวิชา (รหัสวิชา ชั้น ภาคเรียน เวลา คำอธิบายรายวิชา)
--   curriculum_units              หน่วยการเรียนรู้ของแต่ละรายวิชา (ชื่อ เวลา สาระสำคัญ)
--   curriculum_indicators         ตัวชี้วัด (รหัส มาตรฐาน คำอธิบาย)
--   curriculum_unit_indicators    ตัวชี้วัดที่ใช้ในแต่ละหน่วย พร้อมประเภท ระหว่างทาง/ปลายทาง
--   curriculum_competencies       สมรรถนะสำคัญของผู้เรียน 5 ประการ
--   curriculum_unit_competencies  สมรรถนะที่ใช้ในแต่ละหน่วย
--
-- สิทธิ์: ทุกบัญชีเจ้าหน้าที่ที่เข้าแดชบอร์ดได้ อ่านได้ · เพิ่ม/แก้/ลบ ได้เฉพาะแอดมิน · anon เข้าไม่ได้
-- รันซ้ำได้ (CREATE IF NOT EXISTS และ ON CONFLICT DO UPDATE) · ต้องมีฟังก์ชัน is_admin() / can_access_dashboard() อยู่แล้ว
-- ข้อสังเกต: ชื่อหน่วย ม.3 หน่วยที่ 2 เก็บตามต้นฉบับ "ผ้าและการตัดเย็ย" (น่าจะหมายถึง "ตัดเย็บ") — ถ้าต้องการแก้ ให้รันคำสั่ง UPDATE ท้ายไฟล์

CREATE TABLE IF NOT EXISTS public.curriculum_courses (
  course_code   text PRIMARY KEY,
  grade         text NOT NULL,
  term          smallint NOT NULL CHECK (term IN (1, 2)),
  subject_name  text NOT NULL,
  learning_area text NOT NULL,
  course_type   text NOT NULL,
  hours         integer NOT NULL CHECK (hours > 0),
  description   text,
  created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.curriculum_units (
  course_code text NOT NULL REFERENCES public.curriculum_courses (course_code) ON DELETE CASCADE ON UPDATE CASCADE,
  unit_no     integer NOT NULL,            -- หน่วยที่ตามเอกสารหลักสูตร
  seq         integer NOT NULL,            -- ลำดับหน่วยในรายวิชานี้
  name        text NOT NULL,
  hours       integer NOT NULL CHECK (hours > 0),
  essence     text,                        -- สาระสำคัญ
  PRIMARY KEY (course_code, unit_no)
);

CREATE TABLE IF NOT EXISTS public.curriculum_indicators (
  indicator_code text PRIMARY KEY,         -- เช่น ง 1.1 ม.1/1
  grade          text NOT NULL,
  standard       text NOT NULL,            -- เช่น ง 1.1
  description    text NOT NULL
);

CREATE TABLE IF NOT EXISTS public.curriculum_unit_indicators (
  course_code    text NOT NULL,
  unit_no        integer NOT NULL,
  indicator_code text NOT NULL REFERENCES public.curriculum_indicators (indicator_code) ON UPDATE CASCADE,
  kind           text NOT NULL CHECK (kind IN ('ระหว่างทาง', 'ปลายทาง')),
  PRIMARY KEY (course_code, unit_no, indicator_code),
  FOREIGN KEY (course_code, unit_no) REFERENCES public.curriculum_units (course_code, unit_no) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE IF NOT EXISTS public.curriculum_competencies (
  competency_no smallint PRIMARY KEY,
  name          text NOT NULL
);

CREATE TABLE IF NOT EXISTS public.curriculum_unit_competencies (
  course_code   text NOT NULL,
  unit_no       integer NOT NULL,
  competency_no smallint NOT NULL REFERENCES public.curriculum_competencies (competency_no),
  PRIMARY KEY (course_code, unit_no, competency_no),
  FOREIGN KEY (course_code, unit_no) REFERENCES public.curriculum_units (course_code, unit_no) ON DELETE CASCADE ON UPDATE CASCADE
);

-- สิทธิ์: อ่านได้ทุกบัญชีเจ้าหน้าที่ · แก้ได้เฉพาะแอดมิน
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['curriculum_courses', 'curriculum_units', 'curriculum_indicators',
                           'curriculum_unit_indicators', 'curriculum_competencies', 'curriculum_unit_competencies']
  LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('REVOKE ALL ON public.%I FROM anon', t);
    EXECUTE format('REVOKE ALL ON public.%I FROM public', t);
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t);
    EXECUTE format('DROP POLICY IF EXISTS "Staff reads %1$s" ON public.%1$I', t);
    EXECUTE format('CREATE POLICY "Staff reads %1$s" ON public.%1$I FOR SELECT USING (public.can_access_dashboard())', t);
    EXECUTE format('DROP POLICY IF EXISTS "Admin writes %1$s" ON public.%1$I', t);
    EXECUTE format('CREATE POLICY "Admin writes %1$s" ON public.%1$I FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin())', t);
  END LOOP;
END $$;

-- ───────── ข้อมูล ─────────
ON CONFLICT (course_code) DO UPDATE SET
  grade = EXCLUDED.grade, term = EXCLUDED.term, subject_name = EXCLUDED.subject_name, learning_area = EXCLUDED.learning_area,
  course_type = EXCLUDED.course_type, hours = EXCLUDED.hours, description = EXCLUDED.description;

ON CONFLICT (competency_no) DO UPDATE SET name = EXCLUDED.name;

ON CONFLICT (indicator_code) DO UPDATE SET grade = EXCLUDED.grade, standard = EXCLUDED.standard, description = EXCLUDED.description;

ON CONFLICT (course_code, unit_no) DO UPDATE SET seq = EXCLUDED.seq, name = EXCLUDED.name, hours = EXCLUDED.hours, essence = EXCLUDED.essence;

ON CONFLICT (course_code, unit_no, indicator_code) DO UPDATE SET kind = EXCLUDED.kind;

ON CONFLICT DO NOTHING;

NOTIFY pgrst, 'reload schema';

-- ถ้าต้องการแก้ชื่อหน่วย ม.3 หน่วยที่ 2 ให้ถูกต้อง ให้เอาเครื่องหมาย -- ออกแล้วรัน:
-- UPDATE public.curriculum_units SET name = 'ผ้าและการตัดเย็บ' WHERE course_code = 'ง23101' AND unit_no = 2;

-- ผลตรวจหลังนำเข้า: ควรได้ 6 แถว เวลารวมหน่วย = 20 ทุกรายวิชา
SELECT c.course_code AS "รหัสวิชา", c.grade AS "ชั้น", c.term AS "ภาค", c.hours AS "เวลาที่กำหนด",
       count(u.*) AS "จำนวนหน่วย", coalesce(sum(u.hours), 0) AS "เวลารวมหน่วย"
FROM public.curriculum_courses c
LEFT JOIN public.curriculum_units u USING (course_code)
GROUP BY c.course_code, c.grade, c.term, c.hours
ORDER BY c.course_code;
